mapper.insert:
/* 지출 등록 */
INSERT INTO EXPND
     ( PET_SN
     , MBR_SN
     , RECPT_SN
     , EXPND_CLSF_CD
     , EXPND_INPT_MTH_CD
     , EXPND_AMT
     , EXPND_PLCUS_NM
     , DTL_MTTR
     , EXPND_YMD
     , IDMPT_DMND_ID
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     )
VALUES
     ( #{petSn}
     , #{mbrSn}
     , #{recptSn}
     , #{expndClsfCd}
     , #{expndInptMthCd}
     , #{expndAmt}
     , #{expndPlcusNm}
     , #{dtlMttr}
     , #{expndYmd}
     , #{idmptDmndId}
     , 'N'
     , NOW()
     , NOW()
     )

mapper.select:
/* 멱등 요청 ID 로 내 지출 조회 */
SELECT 
  FROM EXPND E
  LEFT JOIN PET P
    ON P.PET_SN = E.PET_SN
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.IDMPT_DMND_ID IN

        #{idmptDmndId}

 ORDER BY E.EXPND_SN

/* 같은 날짜·카테고리·금액·반려동물의 내 지출 조회(공용은 공용끼리, 사용처·내용 제외) */
SELECT 
  FROM EXPND E
  LEFT JOIN PET P
    ON P.PET_SN = E.PET_SN
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.EXPND_YMD = #{expndYmd}
   AND E.EXPND_CLSF_CD = #{expndClsfCd}
   AND

        (E.PET_SN <=> #{line.petSn} AND E.EXPND_AMT = #{line.expndAmt})

 ORDER BY E.EXPND_SN

/* 기간 내 지출 합계 */
SELECT COALESCE(SUM(EXPND_AMT), 0)
  FROM EXPND
 WHERE MBR_SN = #{mbrSn}
   AND DEL_YN = 'N'
   AND EXPND_YMD BETWEEN #{startYmd} AND #{endYmd}

/* 알림 받을 월 지출 한도 조회(한도 없음·알림 끔이면 NULL) */
SELECT CASE WHEN EXPND_LIM_NOTI_RCPTN_YN = 'Y' THEN MM_EXPND_LIM_AMT END
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

/* 조건에 맞는 내 지출 건수 */
SELECT COUNT(*)
  FROM EXPND E
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'

/* 조건에 맞는 내 지출 합계 */
SELECT COALESCE(SUM(E.EXPND_AMT), 0)
  FROM EXPND E
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'

/* 내 지출이 있는 연월(최신순, 기준일 이후 제외) */
SELECT DATE_FORMAT(E.EXPND_YMD, '%Y-%m') AS YM
  FROM EXPND E
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.EXPND_YMD <= #{endYmd}
 GROUP BY DATE_FORMAT(E.EXPND_YMD, '%Y-%m')
 ORDER BY YM DESC

/* 기간 내 카테고리별 합계(금액 큰 순, 기타는 마지막) */
SELECT E.EXPND_CLSF_CD
     , SUM(E.EXPND_AMT) AS TOTAL_EXPND_AMT
  FROM EXPND E
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.EXPND_YMD BETWEEN #{startYmd} AND #{endYmd}
 GROUP BY E.EXPND_CLSF_CD
 ORDER BY CASE WHEN E.EXPND_CLSF_CD = #{etcClsfCd} THEN 1 ELSE 0 END
        , TOTAL_EXPND_AMT DESC

/* 기간 내 공용 지출 합계 */
SELECT COALESCE(SUM(EXPND_AMT), 0)
  FROM EXPND
 WHERE MBR_SN = #{mbrSn}
   AND DEL_YN = 'N'
   AND PET_SN IS NULL
   AND EXPND_YMD BETWEEN #{startYmd} AND #{endYmd}

/* 기간 내 금액 큰 지출 3건 */
SELECT 
  FROM EXPND E
  LEFT JOIN PET P
    ON P.PET_SN = E.PET_SN
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.EXPND_YMD BETWEEN #{startYmd} AND #{endYmd}
 ORDER BY E.EXPND_AMT DESC, E.EXPND_YMD DESC, E.EXPND_SN DESC
 LIMIT 3

/* 기준일 이전 내 지출 존재 여부(지난달 비교 대상) */
SELECT EXISTS (SELECT 1
                 FROM EXPND
                WHERE MBR_SN = #{mbrSn}
                  AND DEL_YN = 'N'
                  AND EXPND_YMD < #{ymd})

/* 내 지출 한 건(목록 항목 형태) */
SELECT 
  FROM EXPND E
  LEFT JOIN PET P
    ON P.PET_SN = E.PET_SN
 WHERE E.EXPND_SN = #{expndSn}
   AND E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'

mapper.update:
/* 지출 수정 */
UPDATE EXPND
   SET PET_SN = #{petSn}
     , EXPND_CLSF_CD = #{expndClsfCd}
     , EXPND_AMT = #{expndAmt}
     , EXPND_PLCUS_NM = #{expndPlcusNm}
     , DTL_MTTR = #{dtlMttr}
     , EXPND_YMD = #{expndYmd}
     , MDFCN_DT = NOW()
 WHERE EXPND_SN = #{expndSn}
   AND MBR_SN = #{mbrSn}
   AND DEL_YN = 'N'

/* 내 지출 삭제(번호 목록) */
UPDATE EXPND
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND DEL_YN = 'N'
   AND EXPND_SN IN

        #{expndSn}

/* 조건에 맞는 내 지출 삭제 */
UPDATE EXPND E
   SET E.DEL_YN = 'Y'
     , E.MDFCN_DT = NOW()
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'

/* 월 지출 한도 저장(처음 저장이면 한도 알림 수신을 켬, 수신 여부를 먼저 계산) */
UPDATE MBR
   SET EXPND_LIM_NOTI_RCPTN_YN = CASE WHEN MM_EXPND_LIM_AMT IS NULL THEN 'Y'
                                      ELSE EXPND_LIM_NOTI_RCPTN_YN END
     , MM_EXPND_LIM_AMT = #{mmExpndLimAmt}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}

mapper.select:
/* 한도 알림 수신 여부 */
SELECT EXPND_LIM_NOTI_RCPTN_YN
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

/* 월 지출 한도(미설정이면 NULL) */
SELECT MM_EXPND_LIM_AMT
  FROM MBR
 WHERE MBR_SN = #{mbrSn}
